pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.deposit{value: 1 ether}();
        uint256 balBefore = address(user).balance;
        vm.prank(user);
        c.refund();
        uint256 balAfter = address(user).balance;
        assertEq(balAfter - balBefore, 1 ether);
    }
}
